L["Also a grey ! for quests you can still pick up that no longer give experience."] = "Также серый ! для заданий, которые еще можно взять, но они уже не дают опыта."
L["Also a grey star on the map for the rares you have killed."] = "Также серая звезда на карте для убитых редких противников."
L["Also hidden for a few seconds after you dismount, while the pet comes back."] = "Также скрыто несколько секунд после спешивания, пока питомец возвращается."
L["Also Import"] = "Также импортировать"
L["Also in use on"] = "Также используется на"
L["Also keeps your last whispers and group chat lines with each player."] = "Также сохраняет последние сообщения шепотом и в групповом чате с каждым игроком."
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "Также открывает карту мира на путевой точке, чтобы было видно, где она. Только вне боя."
L["Also prints the summary when you leave a raid."] = "Также выводит сводку при выходе из рейда."
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "Также напоминает в подземельях. По умолчанию выключено: в них редко есть травы или руда."
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "Также показывает прибыль каждого рецепта справа в его строке, зеленым или красным. Рецепты с неизвестной прибылью ее не показывают."
L["Also thanks players in your party or raid."] = "Также благодарит игроков в вашей группе или рейде."
L["Also used inside dungeons and raids."] = "Также используется в подземельях и рейдах."
L["Also warns about rares you have killed before."] = "Также предупреждает о редких противниках, которых вы уже убивали."
L["Also warns while your pet is set to passive."] = "Также предупреждает, пока питомец в пассивном режиме."
L["Also warns while your pet's health is under the threshold, in combat too."] = "Также предупреждает, пока здоровье питомца ниже порога, в том числе в бою."
L["Also worth a look"] = "Также стоит взглянуть"
