L["An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above."] = "Ошибка «Инвентарь заполнен» показывает строку на 20 секунд, даже если свободных ячеек больше порога выше."
L["An alt that already has this macro, by name and text or text alone, uses its own."] = "Альт, у которого уже есть этот макрос, по имени и тексту или только по тексту, использует свой."
L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "Кнопка «Альты» рядом с вкладкой «Отправить» почтового ящика перечисляет ваших персонажей в этом мире и фракции с уровнем и золотом. Выберите одного, чтобы заполнить поле «Кому»."
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "Кнопка «Прикрепить» рядом с вкладкой «Отправить» почтового ящика: прикрепите все хозяйственные товары, один их тип или непривязанную экипировку одним щелчком."
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "ID, скрытый игрой: «Скрыть строку» убирает ее из подсказки, «Показать скрытые» показывает строку со словом «Скрыто» вместо числа."
L["An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster."] = "Предмет, который на аукционе стоит дороже, чем у торговца, оценивается по цене аукциона из последнего сканирования цен или TradeSkillMaster."
