L["At a profession trainer who teaches any of your favourite recipes that you can learn now (star one before its name, or right-click it in the list), a window beside the trainer's lists them with their cost: Learn one, or Learn All."] = "У учителя профессии, который обучает избранным рецептам, доступным вам сейчас (отметьте звездой перед названием или правым щелчком в списке), рядом появляется окно с ними и стоимостью: изучите один или все."
L["At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you."] = "У торговца, который их продает, докупает классовые реагенты и боеприпасы до нужного количества и выводит потраченное. По умолчанию выключено: тратит золото за вас."
L["At level %d"] = "На уровне %d"
L["At login, names any of your characters with mail that expires within three days. It knows each character's mail from the last time it opened a mailbox."] = "При входе называет ваших персонажей, у которых почта истекает в течение трех дней. Почта каждого персонажа известна с последнего открытия почтового ящика."
L["At the auction house, a window beside it lists the patterns, plans and manuals of your favourite recipes that you have not learned or bought, with what they cost now. Buy finds the cheapest and asks before Accept buys it."] = "На аукционе рядом появляется окно с выкройками, чертежами и руководствами избранных рецептов, которые вы еще не изучили и не купили, с текущей ценой. «Купить» находит самый дешевый и спрашивает, прежде чем «Принять» его купит."
