L["Buys from this merchant, in one click, every checked reagent it sells, for that many crafts, whatever is already in your bags. Set the number with the - and + beside it; uncheck a reagent to leave it out."] = "Покупает у этого торговца одним щелчком все отмеченные реагенты, которые он продает, на указанное число изделий, без учета того, что уже есть в сумках. Задайте число кнопками - и + рядом; снимите отметку с реагента, чтобы пропустить его."
