L["Buys on the auction house the materials for that many crafts, whatever is already in your bags: every checked reagent that vendors do not sell. Set the number with the - and + beside it; uncheck a reagent to leave it out. Each material asks for the price now and waits for you to confirm."] = "Покупает на аукционе материалы на указанное число изделий, без учета того, что уже есть в сумках: все отмеченные реагенты, которых нет у торговцев. Задайте число кнопками - и + рядом; снимите отметку с реагента, чтобы пропустить его. Для каждого материала запрашивается текущая цена и ждется ваше подтверждение."
L["Buys what your bags lack of this merchant's reagents for %d crafts, the orange number next to the recipe, so Create All can make them all. Uncheck a reagent to leave it out."] = "Покупает недостающие в сумках реагенты этого торговца на %d изделий (оранжевое число у рецепта), чтобы «Создать все» сделало их все. Снимите отметку с реагента, чтобы пропустить его."
