L["Every paladin in your group running Naowh Forever, and the blessing they give each class. Click an icon to change it: your own row always, anyone's while you lead the group or are an assistant. Only what that paladin has learned is offered, and changes reach them straight away."] = "Каждый паладин в группе с Naowh Forever и благословение, которое он дает каждому классу. Щелкните по значку, чтобы изменить: свою строку всегда, чужие, если вы лидер группы или помощник. Предлагается только изученное этим паладином, изменения доходят сразу."
