L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "Для паладинов кнопка на каждый класс в группе. Левый щелчок благословляет следующего участника этого класса, которому нужно, сначала тех, у кого нет, пропуская мертвых и вне досягаемости. Правый щелчок по классу выбирает его благословение или открывает список игроков. Переместите в редакторе HUD. В предпросмотре: правый щелчок по классу для благословения, щелчок по ауре для выбора, колесо для размера и Shift-колесо для интервала, тяните промежуток после ауры, x скрывает кнопку, + возвращает."
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Для персонажей Skyborne: силовые линии (Альянс, для умения «Чтение силовых линий») или слияния стихий (Орда, для умения «Небесный взор») отмечены на карте мира. Игра их не отмечает: аддон знает найденные игроками и сохраняет каждое новое, на котором вы применили расовую способность. Другие расы меток не видят."
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "Для вашего класса: импортирует этот набор один раз на новом персонаже, на 1 уровне без опыта."
L["For your level"] = "Для вашего уровня"
