L["How big the stars are on the map."] = "Размер звезд на карте."
L["How big the tracker is."] = "Размер отслеживания."
L["How close a book has to be before it pings."] = "Как близко должна быть книга для сигнала."
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "Насколько раньше окончания текущего заклинания можно нажать следующее, в миллисекундах. Большинству подходит 100-400: меньше отзывчивее, больше прощает задержку. Ближний бой около пинга + 100, дальний около пинга + 150."
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "С какого момента значок начинает исчезать, от 0% (сразу) до 95% (в самом конце)."
L["How far below your level gear has to be for Old Common Gear."] = "Насколько ниже вашего уровня должна быть экипировка для «Старой обычной экипировки»."
L["How Group Inspect shows a party and a raid, with sample players."] = "Как осмотр группы показывает группу и рейд, на примере игроков."
L["How little Camp Benefits time counts as needing a refresh."] = "Какой остаток бонусов лагеря считается требующим обновления."
L["How long an interrupted cast stays up. 0 hides it at once."] = "Сколько остается видно прерванное заклинание. 0 скрывает сразу."
L["How long before the effect runs out it shows again."] = "За сколько до окончания эффекта показывается снова."
L["How long each line stays before it fades."] = "Сколько каждая строка держится перед исчезанием."
L["How long it takes to get there at your speed."] = "Сколько времени займет путь с вашей скоростью."
L["How long the current fight has run, on screen while you fight. Move it in the HUD Editor."] = "Длительность текущего боя на экране во время боя. Переместите в редакторе HUD."
L["How long the fight lasted, in chat when it ends."] = "Длительность боя, в чат по его окончании."
L["How long the next level takes at your current rate."] = "Сколько займет следующий уровень при текущем темпе."
L["How long this session has run."] = "Длительность этого сеанса."
L["How many crafts Add to List adds the materials for."] = "На сколько изделий «Добавить в список» добавляет материалы."
L["How many crafts Buy buys the materials for."] = "На сколько изделий «Купить» покупает материалы."
L["How many crafts to ask for."] = "Сколько изделий заказать."
L["How many decimals the per mana numbers show."] = "Сколько знаков после запятой у чисел за ед. маны."
L["How many icons fit in a row before the next row starts."] = "Сколько значков в строке до начала следующей."
L["How many new instances this account has entered this hour."] = "Сколько новых подземелий посетила эта учетная запись за час."
L["How many of this material you hand the crafter. Ticking the box fills in all the crafts need; - and + change it by one."] = "Сколько этого материала вы передаете ремесленнику. Отметка заполняет нужное для всех изделий; - и + меняют на единицу."
L["How many to carry. 0 stops reminding you about it."] = "Сколько носить с собой. 0 отключает напоминание."
L["How Much Stronger"] = "Насколько сильнее"
L["How much stronger it makes you by your stat weights, as +%."] = "Насколько сильнее это делает вас по весам характеристик, в +%."
