L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "Открывает ссылку на профессию другого игрока в этом окне, чтобы заказать у него изделия. Выберите рецепт, задайте число изделий, отметьте свои материалы (или введите количество) и нажмите «Добавить в порядок». В заказе справа есть предлагаемые чаевые за изделие, их можно изменить; «Спросить» отправляет ремесленнику по сообщению на изделие с количеством, вашими материалами и чаевыми: в чат группы, если он в вашей группе, иначе шепотом. Для цен и чаевых нужно сканирование аукциона."
L["Opens its settings and leaves the HUD Editor."] = "Открывает его настройки и выходит из редактора HUD."
L["Opens the Aim Trainer now, out of combat."] = "Открывает тир сейчас, вне боя."
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "Открывает окно AuraBuffs, где каждый предмет добавляется по ID предмета и ID заклинания баффа."
L["Opens the Consumable Bar's settings."] = "Открывает настройки панели расходуемых."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Открывает карточку копирования на примере заклинания. Выделите ID или ссылку, затем Ctrl+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Открывает настройки отслеживания заданий путеводителя по подземельям."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Открывает редактор HUD: щелкните по другому элементу Naowh Forever, вместе с которым будет двигаться полоса."
L["Opens the Library Books tracker's settings."] = "Открывает настройки отслеживания книг библиотеки."
L["Opens the planner on its Builds tab."] = "Открывает планировщик на вкладке «Сборки»."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Открывает отслеживание заданий в открытом мире на подземелье, для которого ваши задания."
L["Opens the quest tracker when you enter a dungeon with quests for you."] = "Открывает отслеживание заданий при входе в подземелье с заданиями для вас."
L["Opens the quiz now, or closes it."] = "Открывает викторину сейчас или закрывает ее."
L["Opens the Run Timer settings."] = "Открывает настройки таймера забега."
L["Opens the Sleeping Bag tracker's settings."] = "Открывает настройки отслеживания спального мешка."
L["Opens the Stat Weights window: each stat's worth to your spec, and your best upgrades by them."] = "Открывает окно весов характеристик: ценность каждой характеристики для вашей специализации и лучшие улучшения по ним."
