L["Plays Drop Alert with your list's first BiS, as you set it: up for a roll, dropped, then yours."] = "Проигрывает оповещение о добыче с первым BiS из списка, как вы его настроили: бросок, выпадение, получение."
L["Plays once each time your health drops below the threshold. If the game hides your health from addons mid-fight, it only plays out of combat."] = "Проигрывается каждый раз, когда здоровье падает ниже порога. Если игра скрывает здоровье от аддонов в бою, только вне боя."
L["Plays once when your threat climbs past the threshold, and again only after it drops back below."] = "Проигрывается, когда угроза поднимается выше порога, и снова только после того, как опустится ниже."
L["Plays the map ping and names the book in chat when you come within range of one you still need. Once per book, until you walk away and come back."] = "Проигрывает сигнал карты и называет книгу в чате, когда вы рядом с нужной книгой. Один раз на книгу, пока вы не уйдете и не вернетесь."
L["Plays the map ping when a book is near."] = "Проигрывает сигнал карты, когда рядом книга."
L["Plays the sound again this often while out of range. 0 plays it once."] = "Повторяет звук с этим интервалом, пока вне досягаемости. 0 проигрывает один раз."
L["Plays the sound picked here."] = "Проигрывает выбранный здесь звук."
L["Plays when it is time to refresh the camp."] = "Проигрывается, когда пора обновить лагерь."
L["Plays when the warning comes up, and flashes the game's icon on your taskbar."] = "Проигрывается при появлении предупреждения и мигает значком игры на панели задач."
