L["Shown in combat."] = "Показывается в бою."
L["Shown in dungeons and raids."] = "Показывается в подземельях и рейдах."
L["Shown while you are in a group."] = "Показывается, пока вы в группе."
L["Shown while you have a bow, gun, crossbow, wand or thrown weapon."] = "Показывается, пока у вас лук, ружье, арбалет, жезл или метательное оружие."
L["Shown while you have a weapon in your off hand."] = "Показывается, пока у вас оружие в левой руке."
L["Shown with threat"] = "Показывается с угрозой"
L["Shown: click to hide it."] = "Показано: щелкните, чтобы скрыть."
L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "Показывает боссов и добычу подземелья рядом с картой мира, пока вы внутри."
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "Показывает значок лечебного предмета, как только здоровье падает ниже порога, в том числе в бою: игра сама показывает и скрывает его. Переместите в редакторе HUD."
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "Показывает подсказку примера заклинания со строкой, как ее рисуют ваши настройки."
L["Shows a zone's level range when you hover it on the world map."] = "Показывает диапазон уровней зоны при наведении на нее на карте мира."
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "Показывает значок на экране, пока вы знаете «Поиск трав», «Поиск минералов» или «Поиск рыбы», но ничего не отслеживаете. Щелкните, чтобы начать: левый щелчок для первого, правый для второго, средний для третьего. Наведите, чтобы увидеть, где что. Скрыт в бою. Переместите в редакторе HUD."
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "Показывает каждый шаг спального мешка, как добраться до следующего, и путевую точку."
L["Shows every bonus again; click one on the preview to hide it."] = "Снова показывает все бонусы; щелкните по бонусу в предпросмотре, чтобы скрыть."
L["Shows how many of each you carry."] = "Показывает, сколько каждого у вас с собой."
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "Показывает, опережаете вы или отстаете от других своих персонажей, и окрашивает прошлые уровни соответственно."
L["Shows it again a little before its effect runs out."] = "Показывает снова незадолго до окончания эффекта."
L["Shows only part of the raid."] = "Показывает только часть рейда."
L["Shows or hides the list of every element."] = "Показывает или скрывает список всех элементов."
L["Shows the factions earned where you are beside the world map."] = "Показывает фракции, репутация которых зарабатывается здесь, рядом с картой мира."
L["Shows the key that uses each button."] = "Показывает клавишу, назначенную каждой кнопке."
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "Показывает измеритель с примерными полосами на его месте на экране на десять секунд. Только вне боя."
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "Показывает отрицательные эффекты второго танка рядом с его полосой здоровья, в том числе в бою: стаки сильных ударов, эффекты боссов и все, что вы можете рассеять."
L["Shows the parts of the world map you have not explored yet, darkened."] = "Показывает затемненными неисследованные части карты мира."
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "Показывает строку, только когда сумки заполнены настолько. 0 показывает всегда."
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "Показывает на карте оставшиеся шаги спального мешка; щелкните для путевой точки."
L["Shows the warning with its sound, about your target if you can attack it."] = "Показывает предупреждение со звуком о вашей цели, если ее можно атаковать."
L["Shows this bonus on the bar: %s."] = "Показывает этот бонус на полосе: %s."
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "Показывает реагенты этого рецепта в списке задач с количеством каждого у вас."
L["Shows this visit's time, coins, and experience."] = "Показывает время, монеты и опыт этого визита."
L["Shows up once you take the talent"] = "Появляется после взятия таланта"
L["Shows who Naowh, the developers, the moderators and our Legendary and Epic patrons are: a badge by their name in chat, a line on their tooltip and, if you want it, a banner when one of them joins your group."] = "Показывает, кто такие Naowh, разработчики, модераторы и наши легендарные и эпические покровители: значок у имени в чате, строка в подсказке и, по желанию, баннер, когда кто-то из них вступает в вашу группу."
L["Shows your BiS stars to players who inspect you with Naowh Forever."] = "Показывает звезды BiS игрокам, которые осматривают вас с Naowh Forever."
L["Shows your note and tag on a player's tooltip."] = "Показывает вашу заметку и метку в подсказке игрока."
L["Shows your other characters' visits."] = "Показывает визиты ваших других персонажей."
