L["Swap equipment sets from a bar, or on their own while you ride or rest."] = "Меняйте комплекты экипировки с панели или автоматически, когда вы верхом или отдыхаете."
L["Swap the window for a small bar with your next visit and your gold, to leave up while you level. Move it by dragging."] = "Замените окно небольшой панелью со следующим визитом и золотом на время прокачки. Перемещается перетаскиванием."
L["Swap your gear sets from a bar."] = "Меняйте комплекты экипировки с панели."
L["Swaps your best scores with your group and guild for the leaderboard."] = "Обменивается лучшими результатами с группой и гильдией для таблицы лидеров."
L["Sweep Color"] = "Цвет развертки"
L["Sweep Delay (s)"] = "Задержка развертки (с)"
L["Sweep Opacity"] = "Непрозрачность развертки"
