L["Swing End Window"] = "Окно конца удара"
L["Swing Timer is off"] = "Таймер атаки выключен"
L["Swirl"] = "Вихрь"
L["Switch between Gridshot, Hexakill and Reflex."] = "Переключение между Gridshot, Hexakill и «Реакцией»."
L["Switch the %s on to set where it sits."] = "Включите %s, чтобы задать его место."
L["Switch, copy and share everything these pages save."] = "Переключайте, копируйте и делитесь всем, что сохраняют эти страницы."
L["Sword"] = "Меч"
L["Tabard"] = "Гербовая накидка"
L["Tag"] = "Метка"
L["Tags"] = "Метки"
