L["Taken"] = "Взято"
L["Takes every item off the bar, after asking."] = "Убирает все предметы с панели, предварительно спросив."
L["Takes every item you have none of off the bar, after asking."] = "Убирает с панели все закончившиеся предметы, предварительно спросив."
L["Remove 1 item you have none of from the Consumable Bar?"] = "Убрать с панели расходуемых 1 закончившийся предмет?"
L["Remove %d items you have none of from the Consumable Bar?"] = "Убрать с панели расходуемых закончившиеся предметы (%d)?"
L["You have at least one of every item on the Consumable Bar."] = "У вас есть хотя бы по одному каждому предмету с панели расходуемых."
L["Takes everything the moment you loot, with Blizzard's loot window kept out of sight, so the feed is all you see. Works with or without the game's auto loot. Hold Shift while looting to get the window back. It also appears whenever something cannot be taken: a group roll, a locked item, or bags too full."] = "Забирает все сразу при добыче, скрывая окно добычи Blizzard, чтобы видна была только лента. Работает с автосбором игры и без него. Удерживайте Shift при добыче, чтобы вернуть окно. Оно также появляется, когда что-то нельзя забрать: групповой бросок, запертый предмет или полные сумки."
L["Takes over from EllesmereUI's inspect window, after a reload"] = "Заменяет окно осмотра EllesmereUI после перезагрузки"
L["Takes over from EllesmereUI's panel, after a reload"] = "Заменяет панель EllesmereUI после перезагрузки"
L["Takes the %d books you carry."] = "Забирает ваши книги (%d)."
L["Takes the book you carry."] = "Забирает вашу книгу."
L["Takes the materials for one craft off the list."] = "Убирает из списка материалы на одно изделие."
L["Takes this craft and its materials off the list."] = "Убирает из списка это изделие и его материалы."
L["Takes this craft off the order."] = "Убирает это изделие из заказа."
L["Takes this material off the shopping list."] = "Убирает этот материал из списка покупок."
L["Talent Builds"] = "Сборки талантов"
L["Talent builds, level by level."] = "Сборки талантов, уровень за уровнем."
L["Talent Points"] = "Очки талантов"
L["Talents"] = "Таланты"
