L["Taught by a quest, not a trainer."] = "Обучает задание, а не учитель."
L["Taught for free by the Artisan doctor:"] = "Бесплатно обучает доктор-мастер:"
L["Tell other Naowh Forever players your zone and level when they ask. Off, you can still ask them; they just learn nothing back."] = "Сообщать другим игрокам Naowh Forever вашу зону и уровень по запросу. Если выключено, вы все равно можете спрашивать, просто они ничего не узнают в ответ."
L["Tells your group what you focused."] = "Сообщает группе, кого вы взяли в фокус."
L["Test Alert"] = "Тест оповещения"
L["Test import of"] = "Тестовый импорт"
L["Test roll"] = "Тестовый бросок"
L["Text"] = "Текст"
L["Text Color"] = "Цвет текста"
L["Text on screen when any piece of gear drops below the threshold. Hidden in combat. Move it in the HUD Editor."] = "Текст на экране, когда прочность любой вещи падает ниже порога. Скрыт в бою. Переместите в редакторе HUD."
L["Text on screen while you have talent points to spend. Hidden in combat. Move it in the HUD Editor."] = "Текст на экране, пока есть нераспределенные очки талантов. Скрыт в бою. Переместите в редакторе HUD."
L["Text selected. Press Ctrl+C to copy."] = "Текст выделен. Нажмите Ctrl+C, чтобы скопировать."
L["Text Size"] = "Размер текста"
L["Text to Speech"] = "Синтез речи"
L["Text while your pet is low on health."] = "Текст, пока у питомца мало здоровья."
L["Text while your pet is missing."] = "Текст, пока нет питомца."
L["Text while your pet is passive."] = "Текст, пока питомец пассивен."
L["Texture Filtering"] = "Фильтрация текстур"
L["Texture Resolution"] = "Разрешение текстур"
