L["Thank With an Emote"] = "Благодарить эмоцией"
L["Thank You"] = "Спасибо"
L["That"] = "Это"
L["That build came out on %s."] = "Эта сборка вышла %s."
L["that filter"] = "этот фильтр"
L["That is not a boss the Dungeon Journal can read right now."] = "Сейчас путеводитель по подземельям не может прочитать этого босса."
L["That is not a Naowh BiS list."] = "Это не список BiS Naowh."
L["That is not a Naowh Forever macro string."] = "Это не строка макроса Naowh Forever."
L["That is not a Naowh Forever talent build."] = "Это не сборка талантов Naowh Forever."
L["That is not a Naowh stat weights line, nor a simulator's export."] = "Это не строка весов характеристик Naowh и не экспорт симулятора."
L["That is not an item you can equip."] = "Этот предмет нельзя надеть."
L["That isn't a Junk List string."] = "Это не строка списка хлама."
L["that item moved in your bags; the row has been refreshed."] = "этот предмет сместился в сумках; строка обновлена."
L["That line has a weight it cannot read: %s."] = "В строке есть вес, который не удается прочитать: %s."
L["That map does not take waypoints."] = "На этой карте нельзя ставить путевые точки."
L["that name is taken"] = "это имя занято"
L["That string holds no consumables list."] = "В этой строке нет списка расходуемых."
L["That talent is not in this class's tree."] = "Этого таланта нет в дереве этого класса."
L["The Aim Trainer can't open in combat."] = "Тир нельзя открыть в бою."
L["The Aim Trainer is off. Turn it on in /nf, QoL, Travel."] = "Тир выключен. Включите его в /nf, Удобства, Путешествие."
L["The auction house gave no final price."] = "Аукцион не сообщил итоговую цену."
L["The auction house has no price for it right now."] = "На аукционе сейчас нет цены для этого."
L["The auction house returned no listings. Try again in a moment."] = "Аукцион не вернул лотов. Попробуйте чуть позже."
L["The AuraBuffs window: the consumables to watch."] = "Окно AuraBuffs: отслеживаемые расходуемые."
L["The bar and the FPS / MS readout fade to Faded Opacity until you hover them. Their buttons still click while faded."] = "Полоса и показатели FPS / MS исчезают до непрозрачности исчезания, пока вы на них не наведете. Их кнопки работают и в исчезнувшем виде."
L["The bar as it shows outside a fight."] = "Полоса, как она выглядит вне боя."
L["The bar as it sits on your screen."] = "Полоса, как она стоит на экране."
L["The best scores of the players you have met, in this mode."] = "Лучшие результаты встреченных вами игроков в этом режиме."
L["The BiS List's own window, and its Stat Weights window."] = "Собственное окно списка BiS и его окно весов характеристик."
L["The BiS rankings behind the BiS List."] = "Рейтинги BiS, лежащие в основе списка BiS."
L["The book count is what players report; not confirmed yet."] = "Число книг сообщают игроки; пока не подтверждено."
L["The boss or place it comes from."] = "Босс или место, откуда это берется."
L["The buffs show while you hover the icon."] = "Баффы показываются при наведении на значок."
L["The build's next talent cannot be taken now: your talents are not the build's."] = "Следующий талант сборки сейчас взять нельзя: ваши таланты не совпадают со сборкой."
L["The calendar cannot be opened from the Top Bar with a gamepad."] = "С геймпадом календарь нельзя открыть с верхней панели."
L["The card at the end of a round."] = "Карточка в конце раунда."
L["The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor."] = "Самые дешевые предметы в сумках рядом значков, от самого дешевого. Ctrl-щелчок по значку удаляет предмет, щелчок продает его при открытом торговце. Средняя кнопка игнорирует предмет. Переместите в редакторе HUD."
L["The class's name, or its class icon, which fits however small the buttons are."] = "Название класса или его значок, который помещается при любом размере кнопок."
L["The color of the line on the tooltip."] = "Цвет строки в подсказке."
L["The Consumable Bar will ask about those items again."] = "Панель расходуемых снова спросит об этих предметах."
L["The consumables your reminders watch"] = "Расходуемые, отслеживаемые напоминаниями"
L["The consumables your reminders watch."] = "Расходуемые, отслеживаемые напоминаниями."
L["The Cozy Sleeping Bag's hidden quest chain, step by step."] = "Скрытая цепочка заданий Уютного спального мешка, шаг за шагом."
L["The crowd control on your target; pick which in the Crowd Control card below."] = "Контроль на вашей цели; выберите, какой, в карточке «Контроль» ниже."
L["The Ctrl-click line, and Click to sell while a vendor is open."] = "Строка Ctrl-щелчка и «Щелчок продает» при открытом торговце."
L["The cursor left still."] = "Курсор неподвижен."
L["The debuffs on your target you pick in the Debuffs card below, like Mortal Strike."] = "Отрицательные эффекты на цели, выбранные в карточке «Отрицательные эффекты» ниже, например Смертельный удар."
L["The default is %s."] = "По умолчанию %s."
L["The default is %s. Click to put it back."] = "По умолчанию %s. Щелкните, чтобы вернуть."
L["The Disenchant window cannot open in combat."] = "Окно распыления нельзя открыть в бою."
L["The Dungeon Quest Tracker's window."] = "Окно отслеживания заданий подземелий."
L["The dungeons on whose ground the list shows. Contested ones and the raids are always listed. Also the switch beside the Journal's search."] = "Подземелья, на территории которых показывается список. Спорные и рейды перечисляются всегда. Также переключатель рядом с поиском журнала."
L["The Edit Items window."] = "Окно «Изменить предметы»."
L["The extra gap between your aura and Righteous Fury and the class buttons."] = "Дополнительный промежуток между аурой и Праведным неистовством и кнопками классов."
L["The fastest way to any waypoint."] = "Самый быстрый путь к любой путевой точке."
L["The first %d of %d; type more to narrow it down."] = "Первые %d из %d; введите больше, чтобы сузить."
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "Когда кто-то впервые пишет, спросить его Naowh Forever о зоне скрытым сообщением аддона. Игроки без него вопроса не увидят."
L["The flight time to each destination when you hover it on the flight master's map."] = "Время полета до каждого пункта при наведении на карте распорядителя полетов."
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "Шрифт чисел урона и исцеления над противниками и над вашим персонажем. Если выключено, шрифт игры не меняется."
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "Шрифт остальной игры: меню, чат, подсказки и имена. Если выключено, шрифты игры не меняются."
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "Шрифт окон и HUD этого аддона. Настройки шрифта функций используют его, если не выбран свой. Сохраняется для этого компьютера.|n|nВступит в силу после /reload."
L["The FPS / MS readout and the online counts on the buttons."] = "Показатели FPS / MS и счетчики в сети на кнопках."
L["The FPS / MS readout stays up."] = "Показатели FPS / MS остаются видимыми."
L["The game does not name this fight yet: its kills count once the raid opens."] = "Игра пока не называет этот бой: убийства будут учитываться после открытия рейда."
L["The game has no PvP rank for you yet. It shows once the season has started."] = "У игры пока нет вашего PvP-звания. Оно появится после начала сезона."
L["The game has no route for %s, and its quest giver's spot is not known."] = "У игры нет маршрута для %s, а место выдающего задание неизвестно."
L["The game is not passing addon messages right now (in an encounter): ask again after it."] = "Сейчас игра не передает сообщения аддонов (идет бой с боссом): спросите после него."
L["The game lists no rank rewards for this season yet."] = "Игра пока не перечисляет награды за звание в этом сезоне."
L["The game would not disenchant this (skill too low?). Skipped until you reload."] = "Игра не стала это распылять (навык слишком низкий?). Пропуск до перезагрузки."
L["The game's own alert sounds first, then the addon's. Each plays as you pick it."] = "Сначала звуки оповещений игры, затем аддона. Каждый проигрывается при выборе."
L["The gap between the two."] = "Промежуток между ними."
L["The gap between two buttons."] = "Промежуток между двумя кнопками."
L["The Gear Sets window, with every set and what you can do with it."] = "Окно комплектов экипировки со всеми комплектами и действиями с ними."
L["The group can be disbanded once the fight is over."] = "Группу можно распустить после боя."
L["The group's paladins and the blessing each gives every class."] = "Паладины группы и благословение, которое каждый дает каждому классу."
L["The guild name under a player's name."] = "Название гильдии под именем игрока."
L["The highest rank this season"] = "Высшее звание в этом сезоне"
L["The icon grows and shrinks with it."] = "Значок растет и уменьшается вместе с ним."
L["The inspect window in the BiS List's look, with their score, gear check, talents and history."] = "Окно осмотра в стиле списка BiS, с рейтингом, проверкой экипировки, талантами и историей."
L["The item's cooldown sweeps over its icon."] = "Восстановление предмета развертывается поверх его значка."
L["The item's quality"] = "Качество предмета"
L["The item, your star and what happened, on screen for a while."] = "Предмет, ваша звезда и что произошло, на экране некоторое время."
L["The items the Buffs & Consumables reminders watch."] = "Предметы, отслеживаемые напоминаниями о баффах и расходуемых."
L["The Journal beside the world map: bosses and loot in dungeons, factions outside."] = "Журнал рядом с картой мира: боссы и добыча в подземельях, фракции снаружи."
L["The Journal's own window."] = "Собственное окно журнала."
L["The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing."] = "Клавиша, меняющая «Принимать задания», «Сдавать задания», «Выбирать задания у NPC» и обмен."
L["The key that changes Auto Gossip for that NPC."] = "Клавиша, меняющая автодиалог для этого NPC."
L["The key that opens the BiS List."] = "Клавиша, открывающая список BiS."
L["The key that opens the Journal."] = "Клавиша, открывающая журнал."
L["The key that opens the Quest List window."] = "Клавиша, открывающая окно списка заданий."
L["The last %ds, scrolling %s%s"] = "Последние %d с, прокрутка %s%s"
L["The last fight's time stays on screen until the next one starts."] = "Время последнего боя остается на экране до начала следующего."
L["The last part of each melee swing, shaded."] = "Последняя часть каждого удара ближнего боя, затененная."
L["the last profile cannot be deleted"] = "последний профиль нельзя удалить"
L["The last profile cannot be deleted."] = "Последний профиль нельзя удалить."
L["The latest %d kills. First counted: %s."] = "Последние %d убийств. Первое учтено: %s."
L["The latest %d. First counted: %s."] = "Последние %d. Первое учтено: %s."
L["The leader's zone on each Group Finder listing, and every member's zone when you hover it."] = "Зона лидера в каждом объявлении поиска группы и зона каждого участника при наведении."
L["The level you are on as it runs, then completed levels, newest first."] = "Текущий уровень по ходу, затем пройденные уровни, сначала новые."
L["The line round the bar."] = "Линия вокруг полосы."
L["The list this character uses."] = "Список, который использует этот персонаж."
L["The longest a buff can last to show; longer ones like Arcane Intellect stay hidden."] = "Наибольшая длительность баффа для показа; более долгие, вроде Чародейского интеллекта, скрыты."
L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "Макросы, которые аддон пишет и обновляет для вас вне боя. Включите здесь или перетащите на панели из умных макросов в Кузне Naowh."
L["The Man. The King."] = "Тот самый. Король."
L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "Окно карты, журнал рядом с картой мира и добыча босса у курсора."
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "Пометки в собственном окне персонажа игры (или EllesmereUI), без окна персонажа Naowh. Если оно включено, в его ячейках они уже есть."
L["The Middle-click line."] = "Строка щелчка средней кнопкой."
L["The most recent completed levels."] = "Последние пройденные уровни."
L["the name is empty"] = "имя пустое"
L["The name on it, and the community it is made for."] = "Имя на нем и сообщество, для которого он создан."
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "Кнопка Naowh Forever у миникарты. Пункт в отсеке аддонов и /naowh открывают это окно в любом случае."
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "Буква N Naowh Forever рядом с именем Naowh, разработчиков, модераторов и наших легендарных и эпических покровителей в чате."
L["The newest line stays at the anchor; older lines stack in this direction."] = "Новая строка остается у якоря; старые складываются в этом направлении."
L["The next one frees in "] = "Следующее освободится через "
L["the next rank of %s (cap %d)"] = "следующий ранг %s (предел %d)"
L["The number on each icon counts your bank as well as your bags."] = "Число на каждом значке учитывает банк и сумки."
L["The order the points are taken in"] = "Порядок изучения очков"
L["the pattern"] = "выкройка"
L["The people and projects behind Naowh Forever."] = "Люди и проекты, стоящие за Naowh Forever."
L["The picked boss's loot and abilities, under the map."] = "Добыча и способности выбранного босса под картой."
L["The planner's own window, and a mini bar to leave up while you level."] = "Собственное окно планировщика и мини-панель на время прокачки."
L["The player list opens after combat."] = "Список игроков откроется после боя."
L["The player's guild rank beside their guild name."] = "Звание игрока в гильдии рядом с названием гильдии."
L["The point of the bar that attaches."] = "Точка полосы, которой она прикрепляется."
L["The point of the frame it attaches to."] = "Точка фрейма, к которой она прикрепляется."
L["The purchase failed."] = "Покупка не удалась."
L["The purchase failed; the price may have changed."] = "Покупка не удалась; возможно, цена изменилась."
L["The purchase failed; the price may have changed.|r"] = "Покупка не удалась; возможно, цена изменилась.|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "Отслеживание заданий и обмен заданиями подземелий с группой."
L["The quests that reward a pick you do not have yet."] = "Задания, награждающие выбранным предметом, которого у вас еще нет."
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "Викторина открывается, когда вы садитесь у костра, и закрывается, когда встаете."
L["The raid marker Mark Focus puts on your focus."] = "Рейдовая метка, которую «Метить фокус» ставит на фокус."
L["the rank before"] = "предыдущий ранг"
L["The ready ring shows with GCD Sweep on."] = "Кольцо готовности видно при включенной развертке GCD."
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "Реагенты известных вам заклинаний, например Чародейская пыль, свечи, семена, Символы королей и Воспламеняющийся порошок, по высшему известному рангу."
L["The red time left blinks, to catch your eye."] = "Красное оставшееся время мигает, чтобы привлечь внимание."
L["The same required-level filter applies to every stack, not each item separately."] = "Один фильтр требуемого уровня действует на все стопки, а не на каждый предмет отдельно."
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "Те же комплекты, что в окне персонажа: надевайте, сохраняйте, переименовывайте или удаляйте их в окне комплектов экипировки."
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "То же с великим благословением, для класса с одним общим благословением, пока у вас есть Символы королей."
L["The seconds left when the time turns red; it turns yellow at twice that."] = "Сколько секунд остается, когда время краснеет; желтеет при вдвое большем значении."
L["The serializer libraries are missing from this build."] = "В этой сборке нет библиотек сериализации."
L["The shape of Naowh's arrow."] = "Форма стрелки Naowh."
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "Доля от цены продажи предметов, которую предлагаемые чаевые добавляют сверх возмещения материалов ремесленника. Не меньше 1 с., если не задано 0."
L["The shortest time between two thanks to the same player."] = "Минимальное время между двумя благодарностями одному игроку."
L["The Slot"] = "Ячейка"
L["The slot it is for."] = "Ячейка, для которой это."
L["The slots and stats only"] = "Только ячейки и характеристики"
L["The space between Naowh's arrow and the text under it."] = "Расстояние между стрелкой Naowh и текстом под ней."
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "Специализация, для которой оценивается экипировка. «Автоматически» следует талантам: ветка с наибольшим числом очков (сила зверя друида оценивается на урон; для медведя выберите «Сила зверя (танк)»)."
L["The spot ahead of you, 312 yards away."] = "Место впереди, в 312 м."
L["The spot off to your right."] = "Место справа от вас."
L["The stat weights each spec starts with."] = "Веса характеристик, с которых начинает каждая специализация."
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "Текст незаметности, пока вы в незаметности, а также напоминание, когда нет."
L["The step and distance text under RestedXP's waypoint arrow."] = "Текст шага и расстояния под стрелкой путевой точки RestedXP."
L["The string is damaged: copy it again in full."] = "Строка повреждена: скопируйте ее снова целиком."
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "Предлагаемые чаевые возмещают материалы ремесленника плюс %d%% от цены продажи предметов (от всех материалов, если рецепт не создает предмет), с округлением, не меньше 1 с. Задайте свои чаевые в списке заказа справа. Долю можно изменить в настройках профессий."
L["The swing timer needs WoW: Forever's own swing event."] = "Таймеру атаки нужно собственное событие удара WoW: Forever."
L["The tag in the speaker's class color. Off, it is grey."] = "Метка цветом класса говорящего. Если выключено, серая."
L["the talent above it"] = "талант над ним"
L["The talent builds you saved in the Training Planner."] = "Сборки талантов, сохраненные в планировщике обучения."
L["The Team"] = "Команда"
L["The text in the theme's accent color instead of gold."] = "Текст цветом акцента темы вместо золотого."
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "Тема RestedXP: собственная или одна из тем Naowh."
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "Время между двумя сторонами. Щелкните для календаря (не с геймпадом)."
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "Оставшееся время желтеет, затем краснеет к концу, чтобы было видно, что контроль вот-вот спадет."
L["The time left, turning yellow, then red, as the camp runs down."] = "Оставшееся время желтеет, затем краснеет по мере истечения лагеря."
L["The tint on every button's icon: Naowh's own and any addon's."] = "Оттенок значка каждой кнопки: Naowh и любых аддонов."
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "Помощь планировщика обучения при прокачке: уведомление о новом уровне с заклинаниями для изучения и панель рядом с учителем класса."
L["The unit frame the bar is attached to, or UIParent for the screen."] = "Рамка юнита, к которой прикреплена полоса, или UIParent для экрана."
L["The weights"] = "Веса"
L["The weights for %s."] = "Веса для %s."
L["The window's border fades with it."] = "Граница окна исчезает вместе с ним."
L["The word itself."] = "Само слово."
L["The XP of completed quests, and their text."] = "Опыт за выполненные задания и его текст."
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "Опыт за задания в процессе, бледным отрезком после выполненных."
L["The XP of quests still in progress. By default the completed quests color, faded."] = "Опыт за задания в процессе. По умолчанию цвет выполненных заданий, бледный."
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "Зона говорящего в канале чата, чате гильдии или шепотом перед его сообщением. Игра никогда не сообщает, где находится незнакомец, поэтому игрок получает метку, когда он в поиске группы, вашей гильдии, друзьях или группе, попал в /who или ответил из своего Naowh Forever. Первое сообщение может прийти без метки."
