L["Turn on PvP"] = "Включить PvP"
L["Turn on QoL to edit the Loot Feed here."] = "Включите «Удобства», чтобы изменить ленту добычи здесь."
L["Turn on Quest Givers"] = "Включить выдающих задания"
L["Turn on Rares"] = "Включить редких"
