L["Turn on the BiS List"] = "Включить список BiS"
L["Turn on the BiS List and pick your BiS to see your best upgrades here."] = "Включите список BiS и выберите BiS, чтобы видеть здесь лучшие улучшения."
L["Turn on the BiS List to see your BiS marked here."] = "Включите список BiS, чтобы видеть здесь пометки BiS."
L["Turn on the Campfire reminder to edit the bar here."] = "Включите напоминание о костре, чтобы изменить панель здесь."
