L["Turn on the Dungeon Journal"] = "Включить путеводитель по подземельям"
L["Turn on the Dungeon Journal for each dungeon's levels and quests here."] = "Включите путеводитель по подземельям, чтобы видеть здесь уровни и задания каждого подземелья."
L["Turn on the Dungeon Journal to see the quests that reward your picks, with their chains and waypoints."] = "Включите путеводитель по подземельям, чтобы видеть задания с вашими предметами в награду, их цепочки и путевые точки."
L["Turn on the Dungeon Journal to see what drops in dungeons for this slot."] = "Включите путеводитель по подземельям, чтобы видеть добычу в подземельях для этой ячейки."
L["Turn on the Loot Feed to edit it here."] = "Включите ленту добычи, чтобы изменить ее здесь."
L["Turn on the Swing Timer"] = "Включить таймер атаки"
L["Turn on the Threat Meter"] = "Включить измеритель угрозы"
