L["Turns on"] = "Включает"
L["Turns the ring red while your target is out of melee range. Uses the same ability as the crosshair's melee check, Melee Spell ID included."] = "Окрашивает кольцо в красный, пока цель вне зоны ближнего боя. Использует ту же способность, что и проверка ближнего боя прицела, включая ID заклинания ближнего боя."
L["Turns those settings on in the new profile"] = "Включает эти настройки в новом профиле"
