L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "Ваше окно персонажа (C) в стиле списка BiS: каждая ячейка с пометками, характеристики для вашей специализации и Naowh Score под уровнем. Игра сохраняет окно и все его функции. С EllesmereUI включение этого выключает его окно персонажа, а выключение возвращает, после перезагрузки."
