L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "Опыт в час на небольшой карточке со временем до уровня, временем в игре, длиной сеанса и временем последних уровней. Скрыто на макс. уровне. Наведите для кнопок «Старт», «Пауза» и «Сброс» (также /naowh xp start, pause или reset). Переместите в редакторе HUD."
L["Your experience. Its left end is a darker shade."] = "Ваш опыт. Левый конец более темного оттенка."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "Ваш полет на карточке: оставшееся время, остановки на маршруте и следующая остановка."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "Заклинания вашего фокуса на отдельной полосе, окрашенной по готовности прерывания, с отметкой его восстановления и щитом на непрерываемых. Прерывание: первое из известных вам Зуботычина, Удар щитом, Пинок, Антимагия, Земной шок, Безмолвие и Звериная атака. Переместите в редакторе HUD."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "Имя фокуса, окрашенное по классу, со значком класса над панелью."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "Ваш фокус, заданный через NF Focus: его таймеры продолжают идти, пока вы сражаетесь с другим."
L["Your game macros, not the Smart Macros, as one string to share."] = "Ваши игровые макросы, не умные макросы, одной строкой, чтобы поделиться."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "Глобальное восстановление развертывается по кольцу, а по окончании появляется кольцо готовности."
