L["Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour."] = "Уровень, опыт и процент на одной полосе, с опытом за выполненные задания и бонусом отдыха за заливкой. Заменяет полосу опыта Blizzard, пока включено. Переместите в редакторе HUD. Ctrl + правый щелчок по полосе сбрасывает время сеанса и опыт в час."
