L["%s is now part of Naowh Forever: Combat: delete its old folder from your AddOns folder."] = "%s теперь входит в Naowh Forever: Combat: удалите его старую папку из папки AddOns."
L["%s is now part of Naowh Forever: Utilities: delete its old folder from your AddOns folder."] = "%s теперь входит в Naowh Forever: Utilities: удалите его старую папку из папки AddOns."
L["%s is now part of Naowh Forever: delete its old folder from your AddOns folder."] = "%s теперь входит в Naowh Forever: удалите его старую папку из папки AddOns."
L["%s is no longer part of Naowh Forever: delete its old folder from your AddOns folder."] = "%s больше не входит в Naowh Forever: удалите его старую папку из папки AddOns."
