L[". Ctrl+C to copy it, then paste it on naowh.gg/forever/account."] = ". Нажмите Ctrl+C, чтобы скопировать, затем вставьте на naowh.gg/forever/account."
L["/nf gamble: open Gamble"] = "/nf gamble: открыть «Ставки»"
L["A ! in its own color for quest givers with a dungeon or raid quest."] = "Знак ! своим цветом у выдающих задания для подземелья или рейда."
L["A border round the active step."] = "Граница вокруг активного шага."
L["A border round the whole window."] = "Граница вокруг всего окна."
L["A glow around each reminder icon, since each is a buff that is missing or running out."] = "Свечение вокруг каждого значка напоминания, ведь каждый означает отсутствующий или заканчивающийся бафф."
L["A glow around the icon while it shows."] = "Свечение вокруг значка, пока он виден."
L["A glow around the reminder while you have no Camp Benefits."] = "Свечение вокруг напоминания, пока у вас нет бонусов лагеря."
L["A minimap button that opens %s. Saved for this computer."] = "Кнопка у миникарты, открывающая %s. Сохраняется для этого компьютера."
L["A panel behind the whole window."] = "Подложка под всем окном."
L["A progress bar of the guide, a line, or nothing."] = "Полоса прогресса руководства, линия или ничего."
L["A reminder when a weapon has no sharpening stone, weightstone or oil on it."] = "Напоминание, когда на оружии нет точильного камня, грузика или масла."
L["A row that is done and the steps after the active one."] = "Выполненная строка и шаги после активного."
L["A sample: the meter in the game shows your fights."] = "Образец: измеритель в игре показывает ваши бои."
L["A soft shine along the top of the bar and a glow where your XP ends."] = "Мягкий блеск вдоль верха полосы и свечение там, где кончается опыт."
L["A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level."] = "Текст вокруг полосы: щелкните по нему в предпросмотре, чтобы изменить. Каждый текст показывается в одном месте вокруг полосы: выбор текста, уже показанного в другом месте, переносит его сюда. На макс. уровне видны только «Время в игре» и «Время сеанса»."
L["About %d kills of your level"] = "Убийств вашего уровня: около %d"
L["Accent Color"] = "Цвет акцента"
L["Add more consumables to watch in the AuraBuffs window."] = "Добавьте больше отслеживаемых расходуемых в окне AuraBuffs."
L["Added next to your saved bar sets, never over them"] = "Добавляется рядом с сохраненными наборами панелей, не поверх них"
L["Adds the Naowh themes to RestedXP's theme list, in place of the Naowh window."] = "Добавляет темы Naowh в список тем RestedXP вместо окна Naowh."
L["All Stocked"] = "Все в запасе"
L["All Texts"] = "Все тексты"
L["Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest on this class; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you."] = "Alt-щелчок по награде на выбор в журнале заданий или у выдающего задание сохраняет ее для этого задания на этом классе; повторный Alt-щелчок очищает выбор. Она выбирается при сдаче задания, и «Сдавать задания» берет ее за вас."
L["Ctrl-click an item in your bags to mark it as junk, and sell it at the next vendor."] = "Ctrl-щелчок по предмету в сумках помечает его как хлам, и он будет продан следующему торговцу."
