L["Beside your class trainer, the spells you can learn now, ticked, with their total and Learn Selected. Untick one to leave it."] = "Рядом с учителем класса: заклинания, которые можно изучить сейчас, отмеченные галочкой, с общей стоимостью и кнопкой «Изучить выбранное». Снимите галочку, чтобы пропустить заклинание."
