L["Default: the item you carry, or the kind's usual icon. Last Used: the icon of the food, flask, elixir, scroll or weapon item you used last."] = "По умолчанию: предмет, который у вас есть, или обычный значок этого типа. «Последнее использованное»: значок еды, настоя, эликсира, свитка или предмета для оружия, использованного последним."
L["Disenchant Next Item"] = "Распылить следующий предмет"
L["Or press %s for the next item."] = "Или нажмите %s для следующего предмета."
L["Set a key for this in Key Bindings, under Naowh Forever, or in the Disenchant Window settings."] = "Назначьте клавишу в «Назначении клавиш», в разделе Naowh Forever, или в настройках окна распыления."
L["Disenchants the next item in the Disenchant window while it is open, one item per press, like a click on Disenchant All."] = "Распыляет следующий предмет в окне распыления, пока оно открыто, по одному за нажатие, как щелчок по «Распылить все»."
L["Drag to reorder within this section."] = "Перетащите, чтобы изменить порядок в этом разделе."
L["Dresses the addon's windows as Naowh's own or WoW Forever's, after a reload."] = "Оформляет окна аддона в стиле Naowh или WoW Forever после перезагрузки."
