L["Hides the texts until you hover the bar: the ones around it, or those on it too."] = "Скрывает тексты, пока вы не наведете на полосу: тексты вокруг нее или также на ней."
L["Host left; session ended."] = "Ведущий вышел; игра окончена."
L["Hover Breakdown"] = "Разбивка при наведении"
L["Hovering the bar shows your XP to level, quest and rested XP, and about how many kills are left."] = "При наведении на полосу видны опыт до уровня, опыт за задания и бонус отдыха, а также примерное число оставшихся убийств."
L["How big the text under RestedXP's arrow is."] = "Размер текста под стрелкой RestedXP."
L["How big the whole window is, its text with it."] = "Размер всего окна вместе с текстом."
L["How many steps the list shows at once, the rest by scrolling it."] = "Сколько шагов список показывает сразу; остальные через прокрутку."
L["How solid the background of the active step is."] = "Насколько плотный фон активного шага."
