L["How to play"] = "Как играть"
L["In a raid, with each reminder you show in raids."] = "В рейде, вместе с каждым напоминанием, которое показывается в рейдах."
L["Include My Talents"] = "Учитывать мои таланты"
L["Item level, your BiS, Forever's mark, and an upgrade arrow on bag items."] = "Уровень предмета, ваш BiS, отметка Forever и стрелка улучшения на предметах в сумках."
