L["A name without its last name gets it the next time you log in on that character."] = "Имя без фамилии получит ее при следующем входе этим персонажем."
L["Every module enabled for the full Naowh Forever experience. Great if you're a power user with addons and want all the bells and whistles."] = "Все модули включены для полного опыта Naowh Forever. Отлично подходит опытным пользователям аддонов, которым нужны все функции."
L["Looting, Vendors, Mail & Auction House"] = "Добыча, торговцы, почта и аукцион"
