L["A .png, .tga or .blp file. Make its width and height powers of two, such as 128, 256, 512 or 1024, to be safe; a small one, 128 or 256, is good for a pattern that is repeated with Tile Image, and Tile Size says how wide each repeat is. A .jpg is most likely not read by the game: open it and save it as a .png first."] = "Файл .png, .tga или .blp. Для надежности сделайте ширину и высоту степенями двойки, например 128, 256, 512 или 1024; небольшой файл, 128 или 256, подходит для узора, повторяемого через «Замостить изображением», а «Размер плитки» задает ширину каждого повтора. Файл .jpg игра, скорее всего, не прочитает: откройте его и сначала сохраните как .png."
