L["In the game's Interface\\AddOns folder make a folder of your own, such as MyBackgrounds, and put the file in it, for instance MyBackgrounds\\panel.png. A folder of your own is not touched when add-ons are updated. Restart the game once so it finds the file."] = "В папке игры Interface\\AddOns создайте свою папку, например MyBackgrounds, и положите в нее файл, например MyBackgrounds\\panel.png. Своя папка не затрагивается при обновлении аддонов. Перезапустите игру один раз, чтобы она нашла файл."
L["In the Window card, under Picture, pick Your Own Picture in Image, and write the path from Interface in Custom Image, with backslashes and with the file's extension: Interface\\AddOns\\MyBackgrounds\\panel.png. Pick None or another picture in Image to go back."] = "В карточке «Окно», в разделе «Картинка», выберите «Своя картинка» в поле «Изображение» и введите путь от Interface в поле «Свое изображение», с обратными косыми чертами и расширением файла: Interface\\AddOns\\MyBackgrounds\\panel.png. Чтобы вернуться, выберите «Нет» или другую картинку в поле «Изображение»."
