L["The amounts and the fight time, 0 being the game's own size."] = "Величины и время боя; 0 означает размер игры."
L["The amounts, and the fight time."] = "Величины и время боя."
L["The bars' color when Bar Color is Custom Color."] = "Цвет полос, когда «Цвет полосы» задан как «Свой цвет»."
L["The bars' color: each player's class, your theme's Accent or one you pick."] = "Цвет полос: класс каждого игрока, акцент вашей темы или выбранный вами."
L["The border round the window."] = "Граница вокруг окна."
L["The buttons stacked, or side by side."] = "Кнопки друг над другом или рядом."
L["The buttons, when they are Themed."] = "Кнопки, когда они по теме."
L["The color behind each bar, the Window Color until you pick one."] = "Цвет под каждой полосой; «Цвет окна», пока вы не выберете свой."
L["The color behind each bar, where it is not filled."] = "Цвет под каждой полосой там, где она не заполнена."
L["The color of each class's bars, when Bar Color is Class Colors."] = "Цвет полос каждого класса, когда «Цвет полосы» задан как «Цвета классов»."
L["The color of your own bar when Your Bar is Custom Color."] = "Цвет вашей полосы, когда «Ваша полоса» задана как «Свой цвет»."
L["The column titles' size, font and color."] = "Размер, шрифт и цвет заголовков столбцов."
L["The current fight, everything since the last reset, or a past fight."] = "Текущий бой, все с последнего сброса или прошлый бой."
L["The current fight, or everything since the last reset."] = "Текущий бой или все с последнего сброса."
L["The damage meter is not available"] = "Измеритель урона недоступен"
L["The fastest way anywhere: walking, flights, boats, zeppelins, the tram, portals and your Hearthstone."] = "Самый быстрый путь куда угодно: пешком, полетами, кораблями, дирижаблями, поездом, порталами и камнем возвращения."
L["The fights kept, when the game's figures are cleared, and the way back to the defaults."] = "Сохраняемые бои, когда очищаются данные игры, и возврат к настройкам по умолчанию."
L["The fights kept: when, which, how long, and the per-second figures."] = "Сохраненные бои: когда, какие, сколько длились и показатели в секунду."
L["The figures' color. Their size, font and class colors are behind the cog."] = "Цвет цифр. Размер, шрифт и цвета классов за шестеренкой."
L["The figures' size, font and color."] = "Размер, шрифт и цвет цифр."
L["The first row at the bottom and the rest stacked above it, as some meters do."] = "Первая строка внизу, остальные над ней, как в некоторых измерителях."
L["The game did not find the file. Check the folder name, the spelling and the extension, and that the game was restarted after the file was added."] = "Игра не нашла файл. Проверьте название папки, написание и расширение, а также что игра была перезапущена после добавления файла."
L["The game would not save the layout (%s)."] = "Игра не сохранила макет (%s)."
L["The game's layouts are not available."] = "Макеты игры недоступны."
L["The game's meter has no window to place."] = "У игрового измерителя нет окна для размещения."
L["The game's own damage meter: in your theme, sized and set here instead of in Edit Mode."] = "Собственный измеритель урона игры: в вашей теме, с размером и настройками здесь, а не в режиме редактирования."
L["The game's own sparkle on every quest item, kept on through graphics presets; Glimmer's Effect does not change it."] = "Собственное мерцание игры на каждом предмете для заданий, сохраняемое при смене пресетов графики; параметр «Эффект» модуля «Мерцание» его не меняет."
L["The game's own, in your Accent, or hidden; the mouse wheel still scrolls."] = "Игровая, в цвете акцента или скрыта; колесо мыши все равно прокручивает."
L["The game's own, none, the soft shadow, a thin outline or a thick one."] = "Игровой, нет, мягкая тень, тонкий контур или толстый."
L["The gap between the bars."] = "Промежуток между полосами."
L["The icon's size, style, side and crop."] = "Размер, стиль, сторона и обрезка значка."
L["The icon's size; zero fits it to the bar."] = "Размер значка; ноль подгоняет его под полосу."
L["The list and session names in the title bar."] = "Названия списка и сеанса в заголовке."
L["The list and the session, report, reset, add or close a window, and settings."] = "Список и сеанс, отчет, сброс, добавление или закрытие окна и настройки."
L["The list name in the title bar, 0 being the game's own size."] = "Название списка в заголовке; 0 означает размер игры."
L["The list the window shows."] = "Список, который показывает окно."
L["The list's name, the fight's name, or both."] = "Название списка, название боя или оба."
L["The names on the bars, 0 being the game's own size."] = "Имена на полосах; 0 означает размер игры."
L["The names on the bars."] = "Имена на полосах."
L["The names' color. How a name is written, and its size and font, are behind the cog."] = "Цвет имен. Как пишется имя, его размер и шрифт за шестеренкой."
L["The names' size, which the figures follow unless they have their own."] = "Размер имен; цифры следуют ему, если у них нет своего."
L["The panel a left click opens, the Window Color until you pick one."] = "Панель, открываемая левым щелчком; «Цвет окна», пока вы не выберете свой."
L["The path of your own picture."] = "Путь к вашей картинке."
