L["What a journey may use besides walking, flights and ships."] = "Что маршрут может использовать, кроме ходьбы, полетов и кораблей."
L["What each row has before its figures: icon, rank and name, each with its settings behind its cog."] = "Что в каждой строке перед цифрами: значок, место и имя, у каждого свои настройки за шестеренкой."
L["What it shows in a row."] = "Что показывается в строке."
