L["What you are short on when you reach a city or inn."] = "Чего вам не хватает, когда вы прибываете в город или таверну."
L["When the meter shows: always, in combat, in a group or never."] = "Когда виден измеритель: всегда, в бою, в группе или никогда."
L["When the window shows: always, or only in a place or in combat."] = "Когда видно окно: всегда или только в определенном месте или в бою."
L["When you are not among the rows shown, the last row is yours, with your rank."] = "Если вас нет среди показанных строк, последняя строка ваша, с вашим местом."
L["Where it goes"] = "Куда положить"
L["Where the time sits, and its size, font and color."] = "Где находится время, его размер, шрифт и цвет."
L["Whether the biggest bar or the list's total is a full bar."] = "Что считается полной полосой: самая большая полоса или итог списка."
L["Which column stands where, left to right, in each row: the name, the total, the per-second figure, the share, or another list's total for the same player. Another list's total fills in after the fight."] = "Какой столбец где стоит, слева направо, в каждой строке: имя, итог, показатель в секунду, доля или итог другого списка для того же игрока. Итог другого списка заполняется после боя."
L["Which columns a row has and where, and how numbers, shares and per-second figures are written."] = "Какие столбцы в строке и где, и как пишутся числа, доли и показатели в секунду."
L["Window Background"] = "Фон окна"
L["Window Border"] = "Граница окна"
L["Window Position"] = "Положение окна"
L["Window Width"] = "Ширина окна"
L["With Enchanting open, a Disenchant button at the top of the window opens a window of every item in your bags you can disenchant: green, blue and purple weapons and armor (or type /naowh disenchant). Right-click an item to keep that one copy, or Shift-right-click to keep every copy of it, on any character, until you right-click it again. Disenchant All disenchants the rest one by one, one item per click, as the game asks a click for every disenchant. An item the game will not take (skill too low) is skipped until you reload. Closes when combat starts."] = "Когда открыто наложение чар, кнопка «Распылить» вверху окна открывает окно со всеми предметами в сумках, которые можно распылить: зеленое, синее и фиолетовое оружие и доспехи (или введите /naowh disenchant). Правый щелчок по предмету сохраняет эту копию, а Shift + правый щелчок сохраняет все его копии на любом персонаже, пока вы снова не щелкнете по нему правой кнопкой. «Распылить все» распыляет остальное по одному предмету за щелчок, так как игра требует щелчок для каждого распыления. Предмет, который игра не принимает (слишком низкий навык), пропускается до перезагрузки. Закрывается при начале боя."
L["Writes the per-second figure with /s after it."] = "Пишет показатель в секунду с /с после него."
L["Writes the time as (0:05)."] = "Пишет время как (0:05)."
L["Writes the total and the per-second figure as one text with a bar between: 117 | 23."] = "Пишет итог и показатель в секунду одним текстом с чертой между ними: 117 | 23."
L["Writing"] = "Написание"
