L["HOW TO PLAY\n\nSET UP A SESSION\nEnter the pool in gold-and-silver format: an integer followed by \"g\", then an integer followed by \"s\" (for example, 10g50s). One gold is 100 silver, so 10g50s is 1,050 silver. All roll limits use the pool's total silver value. Party and Raid chat are supported; choose the channel your group is using. Both pool components must be whole numbers.\n\nSelect New Game to announce the session. Players, including the host, join by saying the configured join word in the selected chat. They can leave the lobby by saying the leave word. The host can use Last Call to remind the group, then select Start Rolling once at least two players have joined.\n\nCLASSIC\nWhen the host selects Start Rolling, chat announces that everyone can roll and gives the roll limit. Every joined player rolls from 1 to the pool's total silver value using /roll. With a 10g50s pool, each player rolls from 1 to 1,050. Use Announce Rolls to remind players who still need to roll and show the roll range.\n\nWhen everyone has rolled, the player with the lowest roll pays the player with the highest roll the difference between those original rolls. The difference is silver and is announced in gold-and-silver format (for example, 50 silver is shown as 0g50s). If the highest or lowest roll is tied, only the players tied at that extreme reroll to decide that side's winner or loser. The original high and low rolls determine the amount, even if a tie-break roll changes the order. If every player rolls the same number, nobody pays and everyone rolls again.\n\nDEATHROLL\nAfter the host starts the game, two joined players are selected at random. Gamble announces the selected players, then announces which one was randomly chosen to roll first.\n\nThe first player rolls from 1 to the pool's total silver value. With a 10g50s pool, the first roll is from 1 to 1,050. The two selected players then alternate: after each roll, the next player rolls from 1 to the value just rolled. Use Announce Rolls to identify whose turn it is and the current roll range. The first player to roll 1 loses; the other player wins the pool, announced in gold-and-silver format.\n\nENDING A SESSION\nThe host can select Cancel Session at any time before the session completes. The cancellation is announced in chat and the session ends for everyone. Completed sessions cannot be cancelled.\n\nGamble only announces results; it does not transfer gold. Players settle any announced amount themselves."] = "КАК ИГРАТЬ\n\nНАСТРОЙКА ИГРЫ\nВведите банк в формате золота и серебра: целое число с «g», затем целое число с «s» (например, 10g50s). Один золотой равен 100 серебряным, поэтому 10g50s это 1050 серебра. Все пределы бросков считаются от общей стоимости банка в серебре. Поддерживаются чаты группы и рейда; выберите канал, которым пользуется ваша группа. Обе части банка должны быть целыми числами.\n\nВыберите «Новая игра», чтобы объявить игру. Игроки, включая ведущего, присоединяются, написав заданное слово для входа в выбранный чат. Покинуть лобби можно, написав слово для выхода. Ведущий может использовать «Последний призыв», чтобы напомнить группе, а затем выбрать «Начать броски», когда присоединятся хотя бы два игрока.\n\nКЛАССИКА\nКогда ведущий выбирает «Начать броски», в чате объявляется, что все могут бросать, и называется предел броска. Каждый присоединившийся игрок бросает от 1 до общей стоимости банка в серебре с помощью /roll. С банком 10g50s каждый игрок бросает от 1 до 1050. Используйте «Объявить броски», чтобы напомнить тем, кто еще не бросил, и показать диапазон броска.\n\nКогда все бросили, игрок с наименьшим броском платит игроку с наибольшим броском разницу между этими исходными бросками. Разница считается в серебре и объявляется в формате золота и серебра (например, 50 серебра показывается как 0g50s). Если наибольший или наименьший бросок выпал у нескольких игроков, только они перебрасывают, чтобы определить победителя или проигравшего с этой стороны. Сумму определяют исходные наибольший и наименьший броски, даже если переброс меняет порядок. Если все игроки выбросили одно и то же число, никто не платит и все бросают снова.\n\nСМЕРТЕЛЬНЫЙ БРОСОК\nПосле того как ведущий начинает игру, случайно выбираются два присоединившихся игрока. «Ставки» объявляют выбранных игроков, а затем того, кто случайно выбран бросать первым.\n\nПервый игрок бросает от 1 до общей стоимости банка в серебре. С банком 10g50s первый бросок от 1 до 1050. Затем два выбранных игрока чередуются: после каждого броска следующий игрок бросает от 1 до только что выпавшего значения. Используйте «Объявить броски», чтобы указать, чья очередь, и текущий диапазон броска. Первый, у кого выпадет 1, проигрывает; другой игрок выигрывает банк, который объявляется в формате золота и серебра.\n\nЗАВЕРШЕНИЕ ИГРЫ\nВедущий может выбрать «Отменить игру» в любой момент до ее завершения. Отмена объявляется в чате, и игра заканчивается для всех. Завершенные игры отменить нельзя.\n\n«Ставки» только объявляют результаты и не передают золото. Игроки сами рассчитываются по объявленным суммам."
