L["Add an item ID, drag an item onto its section, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Добавьте ID предмета, перетащите предмет в его раздел или импортируйте список. Для еды учитывается любой бафф «Сытость», для остальных предметов их собственный бафф; ID заклинаний баффа добавляйте только для предмета, дающего другой бафф. Ничего не добавляется автоматически. Наведите на напоминание, чтобы выбрать настроенный предмет из сумок. Напоминания приостанавливаются в бою; меню предметов работают вне боя. Когда и где они показываются, задается в AuraBuffs > Настройки."
